import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Bedienungsanleitung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/usage.md","filePath":"de/guide/usage.md","lastUpdated":1793173149000}`),a={name:`de/guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="bedienungsanleitung" tabindex="-1">Bedienungsanleitung <a class="header-anchor" href="#bedienungsanleitung" aria-label="Permalink to “Bedienungsanleitung”">​</a></h1><h2 id="grundlegendes-spiel" tabindex="-1">Grundlegendes Spiel <a class="header-anchor" href="#grundlegendes-spiel" aria-label="Permalink to “Grundlegendes Spiel”">​</a></h2><h3 id="ziel" tabindex="-1">Ziel <a class="header-anchor" href="#ziel" aria-label="Permalink to “Ziel”">​</a></h3><p>Füllen Sie ein 9×9-Gitter so, dass jede <strong>Zeile</strong>, jede <strong>Spalte</strong> und jeder der neun 3×3-<strong>Blöcke</strong> alle Ziffern von 1 bis 9 genau einmal enthält. In keiner Einheit darf sich eine Ziffer wiederholen.</p><h3 id="so-wird-gespielt" tabindex="-1">So wird gespielt <a class="header-anchor" href="#so-wird-gespielt" aria-label="Permalink to “So wird gespielt”">​</a></h3><ul><li><strong>Zahl setzen</strong>: Tippen oder klicken Sie auf ein leeres Feld und tippen Sie anschließend auf eine Ziffer im Zahlenfeld am unteren Bildschirmrand.</li><li><strong>Notizen (Kandidaten)</strong>: Aktivieren Sie den Notizmodus und tippen Sie auf Felder, um kleine Kandidatenziffern zu schreiben. Hilfreich, um Möglichkeiten im Blick zu behalten.</li><li><strong>Löschen</strong>: Tippen Sie auf die Schaltfläche „Löschen“, um den Wert eines Feldes zu entfernen (im Notizmodus werden die Notizen gelöscht).</li><li><strong>Tipp</strong>: Tippen Sie auf „Tipp“, um den korrekten Wert eines Feldes aufzudecken.</li><li><strong>Rückgängig</strong>: Tippen Sie auf „Rückgängig“, um Ihren letzten Zug rückgängig zu machen (der vollständige Verlauf wird unterstützt).</li></ul><h3 id="schwierigkeitsgrade" tabindex="-1">Schwierigkeitsgrade <a class="header-anchor" href="#schwierigkeitsgrade" aria-label="Permalink to “Schwierigkeitsgrade”">​</a></h3><p>Der Schwierigkeitsgrad bestimmt, wie viele Felder zu Beginn vorausgefüllt (vorgegeben) sind:</p><table tabindex="0"><thead><tr><th>Grad</th><th>Vorgegebene Felder</th><th>Geeignet für</th></tr></thead><tbody><tr><td>Leicht</td><td>45</td><td>Einsteiger und kurze Runden</td></tr><tr><td>Mittel</td><td>36</td><td>Gelegenheitsspieler</td></tr><tr><td>Schwer</td><td>31</td><td>Regelmäßige Löser</td></tr><tr><td>Experte</td><td>27</td><td>Erfahrene Spieler</td></tr><tr><td>Meister</td><td>24</td><td>Rätsel-Meister</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Sudoku-Spielbrett auf dem Mac"></p><h2 id="spielsteuerung" tabindex="-1">Spielsteuerung <a class="header-anchor" href="#spielsteuerung" aria-label="Permalink to “Spielsteuerung”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>Tippen</strong> Sie auf ein leeres Feld, um es auszuwählen</li><li><strong>Tippen</strong> Sie auf eine <strong>Zahl</strong> im Tastenfeld, um sie zu setzen</li><li><strong>Aktivieren Sie den Notizmodus</strong>, um Kandidatennotizen einzugeben oder zu löschen</li><li><strong>Verwenden Sie „Löschen“</strong>, um ein Feld zu leeren</li><li><strong>Verwenden Sie „Tipp“</strong>, wenn Sie nicht weiterkommen</li><li><strong>Verwenden Sie „Rückgängig“</strong>, um Züge zurückzunehmen</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>Klicken</strong> Sie mit der linken Maustaste auf ein leeres Feld, um es auszuwählen</li><li><strong>Geben Sie eine Zifferntaste (1–9) ein</strong> oder klicken Sie auf das Bildschirm-Tastenfeld, um zu setzen</li><li><strong>Aktivieren Sie den Notizmodus</strong> für Kandidatennotizen</li><li><strong>Tastaturkürzel</strong>: <ul><li><code>⌘N</code> — Neues Spiel</li><li><code>⌘Z</code> — Rückgängig</li><li><code>⌘1</code> bis <code>⌘5</code> — Neues Spiel im jeweiligen Schwierigkeitsgrad starten</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="Sudoku-Startbildschirm auf dem iPhone"></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku-Startbildschirm auf dem iPad"></p><h2 id="intelligente-funktionen" tabindex="-1">Intelligente Funktionen <a class="header-anchor" href="#intelligente-funktionen" aria-label="Permalink to “Intelligente Funktionen”">​</a></h2><h3 id="notizsystem" tabindex="-1">Notizsystem <a class="header-anchor" href="#notizsystem" aria-label="Permalink to “Notizsystem”">​</a></h3><p>Wenn Sie den Notizmodus aktivieren, können Sie kleine Kandidatenziffern in leere Felder schreiben. Das intelligente Notizsystem:</p><ul><li><strong>Löscht Notizen in benachbarten Feldern automatisch</strong>: Sobald Sie eine endgültige Zahl setzen, werden die Notizen für diese Ziffer in allen Feldern derselben Zeile, Spalte und desselben Blocks entfernt.</li><li><strong>Umschalten pro Feld</strong>: Wechseln Sie jederzeit zwischen Eingabemodus und Notizmodus.</li></ul><h3 id="fehlerprufung" tabindex="-1">Fehlerprüfung <a class="header-anchor" href="#fehlerprufung" aria-label="Permalink to “Fehlerprüfung”">​</a></h3><p>Eine optionale Fehlerhervorhebung zeigt falsche Eingaben in Rot an – so lernen Sie, ohne das Rätsel zu verderben.</p><h3 id="tagliche-herausforderung" tabindex="-1">Tägliche Herausforderung <a class="header-anchor" href="#tagliche-herausforderung" aria-label="Permalink to “Tägliche Herausforderung”">​</a></h3><p>Täglich wird ein frisches Rätsel im Schwierigkeitsgrad Meister erzeugt. Ihr Fortschritt bei der täglichen Herausforderung wird in den Statistiken mit einer Kalenderansicht Ihrer Serie verfolgt.</p><h3 id="statistiken" tabindex="-1">Statistiken <a class="header-anchor" href="#statistiken" aria-label="Permalink to “Statistiken”">​</a></h3><p>Verfolgen Sie Ihren Sudoku-Weg:</p><ul><li>Gespielte Partien insgesamt und Gewinnquote</li><li>Aktuelle Serie und beste Serie</li><li>Auswertung je Schwierigkeitsgrad: gewonnene Partien, Bestzeit, Durchschnittszeit</li><li>Kalender der täglichen Herausforderung mit Abschlussmarkierungen</li></ul><p><img src="/screenshot-mac-settings.png" alt="Sudoku-Statistiken auf dem Mac"></p><h2 id="designs" tabindex="-1">Designs <a class="header-anchor" href="#designs" aria-label="Permalink to “Designs”">​</a></h2><p>Wählen Sie in den Einstellungen aus acht wunderschönen Farbdesigns:</p><table tabindex="0"><thead><tr><th>Design</th><th>Stil</th></tr></thead><tbody><tr><td>Classic</td><td>Klares Weiß mit blauen Akzenten</td></tr><tr><td>Midnight</td><td>Dunkler Modus mit tiefen Blautönen</td></tr><tr><td>Paper</td><td>Warme Pergamentstruktur</td></tr><tr><td>Forest</td><td>Natürliche Grüntöne</td></tr><tr><td>Ocean</td><td>Ruhige Meeresblautöne</td></tr><tr><td>Sunset</td><td>Warme Orangeverläufe</td></tr><tr><td>Lavender</td><td>Sanfte Violetttöne</td></tr><tr><td>Rose</td><td>Elegante Rosapalette</td></tr></tbody></table><h2 id="icloud-synchronisierung" tabindex="-1">iCloud-Synchronisierung <a class="header-anchor" href="#icloud-synchronisierung" aria-label="Permalink to “iCloud-Synchronisierung”">​</a></h2><p>Wenn Sie auf Ihrem Gerät bei iCloud angemeldet sind:</p><ul><li>Spielstände werden automatisch synchronisiert – setzen Sie auf jedem Gerät fort</li><li>Statistiken und Einstellungen bleiben synchron</li><li>Der Fortschritt bei täglichen Herausforderungen wird zwischen Geräten übertragen</li><li>Erfordert iOS/iPadOS 16+ oder macOS 15+</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>Mit Game Center können Sie:</p><ul><li>In <strong>Ranglisten</strong> um die besten Lösungszeiten je Schwierigkeitsgrad wetteifern</li><li><strong>Erfolge</strong> freischalten: First Solve, Easy/Medium/Hard/Expert/Master Clear, Flawless (ohne Tipps oder Fehler)</li></ul><h2 id="ratsel-drucken-mac" tabindex="-1">Rätsel drucken (Mac) <a class="header-anchor" href="#ratsel-drucken-mac" aria-label="Permalink to “Rätsel drucken (Mac)”">​</a></h2><p>Auf dem Mac können Sie Rätsel direkt aus der App drucken:</p><ol><li>Öffnen Sie den Dialog <strong>Drucken</strong> über die Symbolleiste</li><li>Wählen Sie den Schwierigkeitsgrad (Leicht bis Meister)</li><li>Aktivieren Sie bei Bedarf „Lösungen einschließen“</li><li>Klicken Sie auf <strong>Drucken</strong></li></ol><p>Ideal zum Lösen mit Stift und Papier!</p><h2 id="soundeffekte" tabindex="-1">Soundeffekte <a class="header-anchor" href="#soundeffekte" aria-label="Permalink to “Soundeffekte”">​</a></h2><p>Sudoku bietet dezente Soundeffekte:</p><ul><li>Bestätigung beim Setzen einer Zahl</li><li>Aufgedeckter Tipp</li><li>Fehlerwarnung</li><li>Siegesfeier</li></ul><p>Schalten Sie den Ton in <strong>Einstellungen → Ton</strong> ein oder aus.</p><h2 id="tipps-und-tricks" tabindex="-1">Tipps und Tricks <a class="header-anchor" href="#tipps-und-tricks" aria-label="Permalink to “Tipps und Tricks”">​</a></h2><ul><li><strong>Beginnen Sie mit den Vorgaben</strong> – prüfen Sie Zeilen, Spalten und Blöcke, in denen bereits viele Zahlen stehen.</li><li><strong>Nutzen Sie Notizen</strong> – sie helfen besonders bei den Schwierigkeitsgraden Schwer, Experte und Meister.</li><li><strong>Suchen Sie nach nackten Einern</strong> – hat ein Feld nur einen möglichen Kandidaten, tragen Sie ihn ein.</li><li><strong>Suchen Sie nach versteckten Einern</strong> – kann eine Ziffer in einer Zeile, Spalte oder einem Block nur an einer Stelle stehen, setzen Sie sie dort ein.</li><li><strong>Setzen Sie Tipps sparsam ein</strong> – sie sind gut zum Lernen, doch ein Rätsel ohne Tipps zu lösen, fühlt sich lohnender an.</li><li><strong>Bauen Sie Ihre tägliche Serie auf</strong> – die tägliche Herausforderung ist ideal, um regelmäßig zu üben.</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};